#!/usr/bin/env bash
# Write atomvm_watch.code-workspace with one folder per Mix project (repo root, m5_emu_mix and
# every examples/*/mix.exs, symlinked apps included), so ElixirLS lints and formats each on save.
# VS Code folder paths take no wildcards, hence the generated file. Run from enterShell.
set -euo pipefail
cd "$(dirname "$0")/.."

out=atomvm_watch.code-workspace
folders='    { "path": "." },
    { "path": "m5_emu_mix" }'
for mix in examples/*/mix.exs; do
  [ -e "$mix" ] || continue
  folders+=$',\n    { "path": "'"$(dirname "$mix")"'" }'
done

content=$(cat <<EOF
// Generated by scripts/workspace.sh, do not edit.
{
  "folders": [
$folders
  ],
  "settings": {
    "[elixir]": {
      "editor.formatOnSave": true,
      "editor.defaultFormatter": "JakeBecker.elixir-ls"
    },
    "elixirLS.fetchDeps": false,
    "elixirLS.dialyzerEnabled": false,
    "files.watcherExclude": { "**/_build/**": true, "**/deps/**": true, "**/.devenv/**": true }
  }
}
EOF
)

# Rewrite only on change, so VS Code doesn't prompt to reload on every shell entry.
if [ ! -f "$out" ] || [ "$(cat "$out")" != "$content" ]; then
  printf '%s\n' "$content" > "$out"
fi
